/** `times` × value × pct / 100 in hundredths, rounded to two decimals: half to even, or half up (away from zero)
 *  when `halfUp`. */
function percentOf(value: string, pct: string, times: number, halfUp: boolean): bigint {
  const p = hundredths(value) * hundredths(pct) * BigInt(times); // in 1/10000 of a hundredth
  const a = p < 0n ? -p : p;
  const q = a / 10000n;
  const rem = a % 10000n;
  const r = rem > 5000n || (rem === 5000n && (halfUp || q % 2n === 1n)) ? q + 1n : q;
  return p < 0n ? -r : r;
}

/** A claim's due: the figure fixed when it was settled, otherwise the one its person's last statement bound it to,
 *  otherwise its amount at the rate in force on its date, at least the sheet's floor. Given the sheet's late
 *  charge, an overdue claim's figure gains the late percent of it for every full 30 days overdue (never bound by a
 *  statement; frozen in when settled). Both round by the sheet's policy date (see Late). */
export function claimDue(claim: Claim, rate: string | undefined, floor: string, late?: Late): string {
  if (claim.due !== null) return claim.due;
  const halfUp = roundsHalfUp(claim, late);
  const figure = claim.stated ? (claim.statedDue ?? 'n/a') : due(claim.amount, rate, floor, halfUp);
  if (late === undefined || figure === 'n/a') return figure;
  const steps = lateSteps(claim, late);
  return steps === 0 ? figure : shown(hundredths(figure) + percentOf(figure, late.pct, steps, halfUp));
}

/** A person's due-total: the figures of their claims that count (each at the rate, of the grade in force, on its
 *  date, with its late charge) added up; 'n/a' when their grade has no rate today and none of those claims has a
 *  figure. */
export function personDue(claims: Claim[], rates: Rate[] | undefined, person: Person, late: Late, floor: string): string {
  const counted = claims.filter(counts);
  const figures = counted.map((c) => claimDue(c, rateFor(rates, gradeOn(person, c.date), c.date), floor, late));
  if (rateFor(rates, gradeOn(person, late.today), late.today) === undefined && figures.every((f) => f === 'n/a')) return 'n/a';
  return sum(figures);
}

/** Two-decimal values added up, skipping 'n/a'. */
export function sum(values: string[]): string {
  return shown(values.filter((v) => v !== 'n/a').reduce((s, v) => s + hundredths(v), 0n));
}
import type { Claim } from '../claims/claims';

/** What the late charge on a sheet depends on: its terms (days), its today (yyyy-MM-dd, '' while it loads), its
 *  late percent (two decimals) and its policy date (yyyy-MM-dd; its today while blank): a claim whose `roundsOn` is
 *  before it rounds its live figures half up, one on or after it half to even. */
export type Late = { terms: number; today: string; pct: string; policy: string };

/** Whether the claim's live figures round half up (it rounds on a date before the policy date) rather than half to even. */
export function roundsHalfUp(claim: Claim, late: Late | undefined): boolean {
  return late !== undefined && late.policy !== '' && claim.roundsOn < late.policy;
}

/** Days since 1970-01-01 of a yyyy-MM-dd date. */
function day(date: string): number {
  const [y, m, d] = date.split('-').map(Number);
  return Date.UTC(y, m - 1, d) / 86_400_000;
}

/** A claim's due-by (yyyy-MM-dd): its date plus the sheet's terms in days. */
export function dueBy(claim: Claim, terms: number): string {
  const [y, m, d] = claim.date.split('-').map(Number);
  return new Date(Date.UTC(y, m - 1, d + terms)).toISOString().slice(0, 10);
}

/** Whether a claim is overdue: it is OPEN and its due-by is before the sheet's today. */
export function isOverdue(claim: Claim, terms: number, today: string): boolean {
  return claim.status === 'OPEN' && today !== '' && dueBy(claim, terms) < today;
}

/** How many full 30 days an overdue claim is overdue (0 when it is not overdue, its due is fixed by settling, or it is a
 *  correction, which bears no late charge). */
export function lateSteps(claim: Claim, late: Late): number {
  if (claim.due !== null || claim.amount.trim().startsWith('-') || !isOverdue(claim, late.terms, late.today)) return 0;
  return Math.floor((day(late.today) - day(dueBy(claim, late.terms))) / 30);
}
import type { Claim } from '../claims/claims';
import { gradeOn, type Person } from '../people/people';
import { claimDue, rateFor, sum, type Rate } from '../rates/rates';
import { isOverdue, type Late } from './late';

export { dueBy, isOverdue } from './late';

/** The overdue count and overdue-total (their dues, late charge included, added up, skipping n/a) of the given
 *  claims that count. */
export function overdue(
  claims: Claim[],
  rates: Rate[] | undefined,
  person: Person,
  late: Late,
  floor: string,
): { count: number; total: string } {
  const over = claims.filter((c) => isOverdue(c, late.terms, late.today));
  return { count: over.length, total: sum(over.map((c) => claimDue(c, rateFor(rates, gradeOn(person, c.date), c.date), floor, late))) };
}
